// Parity: site/assets/js/register-conversions.mjs vs cubesat-i2c-tool conversions.py
// (fixtures generated by cubesat-i2c-tool/tools/export_register_map.py).
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import test from 'node:test';
import { convert, parseValueInput, formatFixed } from '../../site/assets/js/register-conversions.mjs';

const fixtures = JSON.parse(await readFile(new URL('./fixtures/register-conversions.json', import.meta.url)));
const map = JSON.parse(await readFile(new URL('../../site/assets/data/register-map.json', import.meta.url)));

test('JS conversions match Python for every register and sample', () => {
  assert.ok(fixtures.length > 400);
  for (const c of fixtures) {
    const reg = c.register || map.devices.find((d) => d.addr === c.device).registers.find((r) => r.addr === c.reg);
    const out = convert(reg, c.data);
    assert.equal(out.raw, c.raw, `${c.device} ${c.reg} ${c.data}`);
    assert.equal(out.text, c.text, `${c.device} ${c.reg} ${c.data}`);
    if (c.value === null) assert.equal(out.value, null);
    else assert.ok(Math.abs(out.value - c.value) <= 1e-12 * Math.max(1, Math.abs(c.value)));
  }
});

test('value parsing and formatter edge cases', () => {
  assert.deepEqual(parseValueInput('0x22 0x00', 2, 'little'), [0x22, 0x00]);
  assert.deepEqual(parseValueInput('0x1234', 2, 'little'), [0x34, 0x12]);
  assert.deepEqual(parseValueInput('-120', 2, 'big'), [0xff, 0x88]);
  assert.throws(() => parseValueInput('0x10000', 2, 'big'));
  assert.equal(formatFixed(2.5, 0), '2'); assert.equal(formatFixed(3.5, 0), '4');
  assert.equal(formatFixed(-0.0005, 3), '-0.001'); assert.equal(formatFixed(9.9996, 3), '10.000');
});
